C3_t -= contract('AB, CD, abc, FG, def, HI, ghi, JK, MN, klj, OP, nom, QR, qrp, wtzyxLAji, wtzyxNHlg, wtzyxMIkh, wtzyxKBmf, wtzyxPFod, wtzyxOGne, wtzyxJDpb, wtzyxRCra, wtzyxQEqc -> t',
    Cg1, Cg5, eps, Cg5,
    eps, Cg5, eps, Cg1,
    Cg5, eps, Cg5, eps,
    Cg5, eps, prop_s.data, prop_l.data,
    prop_l.data, prop_l.data, prop_l.data, prop_l.data,
    prop_l.data, prop_l.data, prop_l.data,
)
C3_t += contract('AB, CD, abc, FG, def, HI, ghi, JK, MN, klj, OP, nom, QR, qrp, wtzyxLAji, wtzyxNHlg, wtzyxMIkh, wtzyxKBmf, wtzyxPFod, wtzyxOGne, wtzyxJEpc, wtzyxRCra, wtzyxQDqb -> t',
    Cg1, Cg5, eps, Cg5,
    eps, Cg5, eps, Cg1,
    Cg5, eps, Cg5, eps,
    Cg5, eps, prop_s.data, prop_l.data,
    prop_l.data, prop_l.data, prop_l.data, prop_l.data,
    prop_l.data, prop_l.data, prop_l.data,
)

# ── MPI reduction (sum over spatial volume) ──
C3_t = core.gatherLattice(
    cp.array(C3_t), [0, -1, -1, -1])

if core.getMPIRank() == 0:
    np.save('pnL_2pt.npy', cp.asnumpy(C3_t))
    print(f'Saved pnΛ 2pt to {out_file}')
